const CITIES = [['Riyadh','Riyadh'],['Jeddah','Jeddah'],['Makkah','Makkah'],['Madinah','Madinah'],['Dammam','Dammam'],['Tabuk','Tabuk'],['Abha','Abha, Asir']];
const combos = [];
for (const c of CITIES) for (const s of SECTORS) combos.push({ sector: s[0], phrase: s[1], city: c[0], cityQ: c[1] });
const idx = Math.floor(Date.now() / 1800000) % combos.length;
const q = combos[idx];
return [{ json: { textQuery: q.phrase + ' in ' + q.cityQ + ', Saudi Arabia', sector: q.sector, city: q.city } }];

const q = $('Build query').first().json;
const res = $input.first().json || {};
const places = res.places || [];
const out = [];
for (const p of places) {
  const name = (p.displayName && p.displayName.text) ? p.displayName.text : '';
  if (!name) continue;
  const site = p.websiteUri || '';
  if (!site) continue;
  const phone = p.internationalPhoneNumber || p.nationalPhoneNumber || '';
  const maps = p.googleMapsUri || '';
  const kind = (p.primaryTypeDisplayName && p.primaryTypeDisplayName.text) ? p.primaryTypeDisplayName.text : '';
  const summary = (p.editorialSummary && p.editorialSummary.text) ? p.editorialSummary.text : '';
  const addr = p.formattedAddress || '';
  let desc = summary ? summary : (kind ? (kind + ' - ' + q.city) : (q.sector + ' - ' + q.city));
  if (addr) desc = desc + ' | ' + addr;
  out.push({ json: { Name: String(name).slice(0,200), Phone: phone, Domain: site, Maps: maps, Description: desc.slice(0,1800), Sector: q.sector, City: q.city, Notes: 'Google Places' } });
}
return out;

const existing = $input.all();
const names = new Set();
const domains = new Set();
for (const e of existing) {
  const j = e.json;
  if (j.name) names.add(String(j.name).toLowerCase().trim());
  if (j.property_domain) {
    const d = String(j.property_domain).replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0].toLowerCase();
    if (d) domains.add(d);
  }
}
const cands = $('Normalize places').all();
const out = [];
const seen = new Set();
for (const c of cands) {
  const j = c.json;
  const nk = String(j.Name).toLowerCase().trim();
  let dk = '';
  if (j.Domain) dk = String(j.Domain).replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0].toLowerCase();
  if (names.has(nk)) continue;
  if (dk && domains.has(dk)) continue;
  const key = nk + '|' + dk;
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json: j });
}
return out;
